card.content:
{
  "conclusion": "今晚火烧云值得冲，建议18:00前到达开阔西向机位，携带广角镜头和三脚架。",
  "evidence": [
    {
      "tool": "sun_times",
      "field": "日落",
      "confidence": "high",
      "note": "日落时间18:06，为火烧云拍摄提供明确时间基准"
    },
    {
      "tool": "sunset_glow_score",
      "field": "评分",
      "confidence": "medium",
      "note": "评分62分，中等水平，可看趋势再定"
    },
    {
      "tool": "weather_forecast",
      "field": "平均云量",
      "confidence": "medium",
      "note": "今日云量30%，有一定云层但非完全覆盖，利于火烧云形成"
    }
  ],
  "confidence": "medium",
  "time_window": "17:30-18:30",
  "locations": [
    {
      "name": "城市西侧开阔高地",
      "reason": "日落方向无遮挡，视野开阔，便于捕捉火烧云"
    },
    {
      "name": "湖边或河边",
      "reason": "水面可反射天空色彩，增强画面层次"
    }
  ],
  "params": [
    {
      "name": "白平衡",
      "value": "日光或阴天",
      "reason": "保留暖色调，增强火烧云氛围"
    },
    {
      "name": "曝光补偿",
      "value": "-0.7EV",
      "reason": "防止高光过曝，保留云层细节"
    }
  ],
  "alternatives": [
    "若云量变化，可改拍晚霞后的蓝调时刻",
    "若天气转差，可改为明晚（云量18%）再冲"
  ],
  "degraded": ""
}
